import{esc,button as b,number as n,input,range,select}from'./ui.js';
import{likelihoodEvents,tally,statisticalQuestions}from'./b04-model.js';
const colors=['#b28150','#688f88','#8e84aa'],names=['红','蓝','绿'];
const bars=(t,m)=>{const top=Math.max(6,...m.heights);return `<svg viewBox="0 0 620 300" class="x-chart" role="img" aria-label="${esc(m.view==='picture'?'图案记录':'条形记录')}"><text x="310" y="22" text-anchor="middle">${m.title==='preference'?'这组记录的偏好':'这份记录'}</text>${Array.from({length:top+1},(_,i)=>`<path d="M55 ${250-i*190/top}H600" stroke="#e2dfd3"/><text x="45" y="${255-i*190/top}" text-anchor="end">${i*m.scale}</text>`).join('')}${t.labels.map((l,i)=>{const x=90+i*160,h=m.heights[i]*190/top;return `${m.view==='picture'?Array.from({length:m.heights[i]},(_,j)=>`<circle cx="${x+40}" cy="${250-(j+.5)*190/top}" r="${Math.min(12,80/top)}" fill="${colors[i]}"/>`).join(''):`<rect x="${x}" y="${250-h}" width="80" height="${h}" fill="${colors[i]}"/>`}<text x="${x+40}" y="276" text-anchor="middle">${esc(l)}</text>`;}).join('')}<text x="5" y="45">${m.y==='count'?'次数':''}</text><text x="550" y="296">${m.x==='category'?'类别':''}</text></svg><p>每${m.view==='picture'?'个图案':'格'}代表 ${m.scale} ${t.labels[0]==='猫'?'只':'票'}</p>`;};
const table=(labels,counts)=>`<table class="x-table"><tr><th>类别</th><th>次数</th></tr>${labels.map((l,i)=>`<tr><td>${esc(l)}</td><td>${counts[i]}</td></tr>`).join('')}</table>`;
export function visual(t,m){switch(t.type){
case'x-sort':return `<div class="x-token-bank">${t.items.map((o,i)=>b('sort-item',esc(o.label),`data-index="${i}" style="color:${colors[o.color]||'#40534a'};font-size:${o.size===undefined?18:o.size?28:16}px" aria-label="物品 ${i+1}：${esc(o.label)}，${o.color===undefined?'':t.rule==='color'?t.labels[o.color]:o.size?'大':'小'}"`)).join('')}</div><div class="x-bowls">${t.labels.map((l,g)=>`<div><b>${esc(l)}</b><p>${m.dest.map((v,i)=>v===g?String(i+1):'').filter(Boolean).join(' · ')||'还没有'}</p></div>`).join('')}</div>${t.ordered?`<p>我的排序：${m.order.map(i=>esc(t.labels[i])).join(' → ')||'还没排'}</p>`:''}`;
case'x-questionsort':return `<div class="x-bowls"><div><b>需要研究变化</b>${statisticalQuestions.filter((_,i)=>m.choices[i]==='vary').map(([q])=>'<p>'+q+'</p>').join('')}</div><div><b>只有固定答案</b>${statisticalQuestions.filter((_,i)=>m.choices[i]==='fixed').map(([q])=>'<p>'+q+'</p>').join('')}</div></div>`;
case'x-questionbuild':return `<div class="x-question-preview"><p>观察对象：${{'group':'这群孩子','self-days':'我这一周的每天','one-once':'我今天一次'}[m.population]||'还没选'}</p><p>记录：${{sport:'最喜欢的运动',minutes:'阅读的分钟数',fixed:'一周有几天'}[m.variable]||'还没选'}</p><p>可能收到的两份记录：${esc(m.answerA)||'…'} ／ ${esc(m.answerB)||'…'}</p></div>`;
case'x-chartlab':return `<p>原始模拟记录：${t.labels.map((l,i)=>esc(l)+' '+t.counts[i]).join('；')}</p>${m.view==='table'?table(t.labels,m.heights.map(v=>v*m.scale)):m.view==='tally'?`<div class="x-tallies">${t.labels.map((l,i)=>`<p>${esc(l)}：${Array.from({length:Math.floor(m.heights[i]*m.scale/5)},()=>'<b>正</b>').join('')} ${'丨'.repeat(m.heights[i]*m.scale%5)}</p>`).join('')}</div>`:bars(t,m)}`;
case'x-variable':return `<div class="x-bowls"><div><b>逐个数</b>${t.labels.filter((_,i)=>m.choices[i]==='count').map(l=>'<p>'+l+'</p>').join('')}</div><div><b>可以有中间值</b>${t.labels.filter((_,i)=>m.choices[i]==='measure').map(l=>'<p>'+l+'</p>').join('')}</div></div><p>2.5 只宠物？ 125.5 cm 身高？</p>`;
case'x-likelihood':return `<div class="x-prob-line">${['不可能','不太可能','一半机会','很可能','一定'].map((l,i)=>`<div><strong>${l}</strong>${m.places.flatMap((v,j)=>v===i?['<p>'+esc(likelihoodEvents[j][0])+'</p>']:[]).join('')}</div>`).join('')}</div>${m.shown?'<p>特意拿出一颗蓝珠作为反例：袋里 7 红 3 蓝，仍有蓝珠可以被抽到。</p>':''}`;
case'x-experiment':return `<p>模拟${{coin:'硬币',die:'骰子',bag:'抽珠（放回）'}[t.kind]} · ${m.draws.length} / ${t.count} 次</p><div class="x-draw-result">${m.draws.length?esc(t.labels[m.draws.at(-1)]):'还没有开始'}</div><p>发生过的结果：${m.draws.map(i=>esc(t.labels[i])).join(' · ')||'—'}</p><table class="x-table"><tr><th>结果</th><th>计数笔画</th><th>次数</th></tr>${t.labels.map((l,i)=>`<tr><td>${esc(l)}</td><td>${'正 '.repeat(Math.floor(m.counts[i]/5))}${'丨'.repeat(m.counts[i]%5)}</td><td>${m.counts[i]}</td></tr>`).join('')}</table><p>已记录 ${m.counts.reduce((a,b)=>a+b,0)} 次</p>`;
case'x-spinner':{const c=tally(m.sectors,t.colors),a=Array.from({length:t.sectors},(_,i)=>`${colors[m.sectors[i]]||'#e3dfd4'} ${i/t.sectors*100}% ${(i+1)/t.sectors*100}%`).join(',');return `<div class="x-spinner" style="background:conic-gradient(${a})" aria-label="${c.map((v,i)=>names[i]+'色 '+v+' 格').join('，')}"></div><p>${c.map((v,i)=>names[i]+' '+v+' 格').join(' · ')}</p>${m.runs.length?table(names.slice(0,t.colors),m.runs.at(-1).counts):'<p>还没模拟；先涂好每一格并预测。</p>'}`;}
case'x-simulation':return `<svg viewBox="0 0 640 270" class="x-chart" aria-label="每轮出现六的比例，所有点均来自实际模拟"><path d="M55 35V230H610" fill="none" stroke="#999"/><path d="M55 ${230-180/6}H610" stroke="#b28150" stroke-dasharray="5 5"/><text x="2" y="${235-180/6}">1/6</text>${[0,.25,.5,1].map(v=>`<text x="48" y="${235-180*v}" text-anchor="end">${v}</text>`).join('')}${[10,100,1000].map((n,i)=>`<text x="${150+185*i}" y="255" text-anchor="middle">每轮 ${n} 次</text>`).join('')}${m.runs.map((r,i)=>`<circle cx="${150+185*[10,100,1000].indexOf(r.n)+(i%5-2)*12}" cy="${230-180*r.hits/r.n}" r="5" fill="${colors[[10,100,1000].indexOf(r.n)]}"><title>${r.hits}/${r.n}</title></circle>`).join('')}</svg><div class="x-run-list">${m.runs.map(r=>`<span>${r.hits}/${r.n} = ${(r.hits/r.n).toFixed(3)}</span>`).join('')}</div><p>另一个可能的例子（示意，不是上图的模拟）：10 次中出 2 次六，比例 0.20；1000 次中出 220 次，比例 0.22。后者反而离 1/6 更远。</p>`;
default:return'';}}
export function controls(t,m){switch(t.type){
case'x-sort':return `<p>选盒子，再点上面的物品：</p><div class="choice-line">${t.labels.map((l,i)=>b('sort-bin',esc(l),`data-index="${i}" aria-pressed="${m.bin===i}"`)).join('')}</div><div class="x-fields">${t.labels.map((l,i)=>n('counts.'+i,l+'有几个',m.counts[i])).join('')}${select('most','最多的一组',m.most,t.labels.map((l,i)=>[i,l]))}${select('fewest','最少的一组',m.fewest,t.labels.map((l,i)=>[i,l]))}</div>${t.ordered?`<p>按从多到少依次点，再点一次可移出：</p>${t.labels.map((l,i)=>b('sort-order',l,`data-index="${i}" aria-pressed="${m.order.includes(i)}"`)).join('')}`:''}`;
case'x-questionsort':return `<div class="x-fields">${statisticalQuestions.map(([q],i)=>select('choices.'+i,q,m.choices[i],[['vary','需要收集变化的记录'],['fixed','固定答案']])).join('')}${select('reason','问一个班的人数为什么仍是固定答案',m.reason,[['one-total','只求一个总数，没有研究个体间的变化'],['many','提到多人就一定是统计问题']])}</div>`;
case'x-questionbuild':{const answers=t.variable==='sport'?['足球','游泳','羽毛球']:['10','20','30'];return `<div class="x-fields">${select('population','准备观察谁',m.population,[['group','这群孩子'],['self-days','我这一周的每天'],['one-once','我今天一次']])}${select('variable','准备记录什么',m.variable,[['sport','最喜欢的运动'],['minutes','阅读分钟数'],['fixed','一周有几天']])}${select('expected','这些记录会怎样',m.expected,[['vary','可能不同，需要收集来看'],['same','固定答案，不用收集']])}${select('answerA','一种可能记录',m.answerA,answers)}${select('answerB','另一种可能记录',m.answerB,answers)}</div>${input('question','把完整问题说出来（可选）',m.question)}${input('why','为什么需要这些记录（可选）',m.why)}`;}
case'x-chartlab':return `${range('scale','每格或图案代表几个',m.scale,1,10)}<div class="x-fields">${t.labels.map((l,i)=>range('heights.'+i,l+'画几格',m.heights[i],0,20)).join('')}</div><div class="choice-line">${[['bar','条形'],['table','表格'],['picture','图案'],['tally','计数笔画']].filter(([v])=>t.vocab||t.compare&&['bar','table'].includes(v)||v===(t.view||'bar')).map(([v,l])=>b('chart-view',l,`data-value="${v}" aria-pressed="${m.view===v}"`)).join('')}</div>${t.vocab?`<div class="x-fields">${select('title','标题说明什么',m.title,[['preference','这组人的偏好'],['time','每天温度变化']])}${select('x','横轴放什么',m.x,[['category','项目类别'],['count','次数']])}${select('y','纵轴放什么',m.y,[['category','项目类别'],['count','次数']])}${select('terms.tally','计数笔画',m.terms.tally,[['marks','每次加一笔'],['times','出现次数']])}${select('terms.frequency','频数',m.terms.frequency,[['marks','笔画形状'],['times','出现次数']])}${select('terms.picture','图案记录',m.terms.picture,[['symbols','用图形与图例表示数量'],['names','只写名称']])}</div>`:''}${n('answer',t.topTwo?'最多两项合计':t.purpose==='exact'?t.labels[1]+'的准确数量':'最多与最少相差',m.answer)}${t.diffPair?n('difference',t.labels[t.diffPair[0]]+'比'+t.labels[t.diffPair[1]]+'多多少',m.difference):''}${t.compare?`<div class="x-fields">${select('most','最多的是哪一项',m.most,t.labels.map((l,i)=>[i,l]))}${select('preferred','这次我选',m.preferred,[['bar','条形'],['table','表格']])}${select('reason','它帮我回答什么',m.reason,[['exact','查某类的准确人数'],['compare','比较类别之间的差距']])}</div>${input('why','它怎样帮到我（可选）',m.why)}`:''}`;
case'x-variable':return `<div class="x-fields">${t.labels.map((l,i)=>select('choices.'+i,l,m.choices[i],[['count','逐个数'],['measure','可有中间值的测量']])).join('')}${select('half','哪个半单位说得通',m.half,[['pets','半只宠物'],['height','半厘米身高']])}</div>`;
case'x-likelihood':return `<p>先选一件事，再放到下面的位置：</p><div class="choice-line">${likelihoodEvents.map(([l],i)=>b('likely-event',l,`data-index="${i}" aria-pressed="${m.event===i}"`)).join('')}</div><div class="choice-line">${['不可能','不太可能','一半机会','很可能','一定'].map((l,i)=>b('likely-place',l,`data-index="${i}"`)).join('')}</div>${b('counterexample','七红三蓝，找一个例外')}${select('word','抽到红珠应该说',m.word,[['likely','很可能'],['certain','一定'],['impossible','不可能']])}`;
case'x-experiment':return `${n('guess','先猜第一种结果会有几次',m.guess,m.prediction!==null?'disabled':'')}${b('experiment-draw','再做一次',m.draws.length===t.count?'disabled':'')}<div class="choice-line">${t.labels.map((l,i)=>b('experiment-tally',l+' ＋ 一笔',`data-index="${i}" data-delta="1"`)+b('experiment-tally','−',`data-index="${i}" data-delta="-1" aria-label="${l}减一笔"`)).join('')}</div>${select('comparison','第一种结果比我的预测',m.comparison,[['higher','更多'],['lower','更少'],['same','一样']])}<small>每次先记录，才做下一次。理想规则的伪随机模拟。</small>`;
case'x-spinner':return `<div class="choice-line">${Array.from({length:t.colors},(_,i)=>b('spinner-color',names[i],`data-index="${i}" aria-pressed="${m.color===i}"`)).join('')}</div><p>点编号，给相应扇区上色：</p><div class="choice-line">${m.sectors.map((c,i)=>b('spinner-sector',String(i+1),`data-index="${i}" style="border-color:${colors[c]||'#ccc'}"`)).join('')}</div>${select('prediction','先判断这几种颜色',m.prediction,[['equal','机会相同'],['unequal','机会不同']])}${b('spinner-run','模拟 100 次并记录')}${select('why','机会相同与否要看',m.why,[['area','各色占的等大份数'],['names','颜色有几个名字'],['trial','这次次数是否完全相同']])}`;
case'x-simulation':return `<div class="choice-line">${select('sample','每轮试几次',m.sample,['10','100','1000'])}${b('simulate','做一轮并画到图上')}</div><p>${[10,100,1000].map(n=>n+' 次一轮：'+m.runs.filter(r=>r.n===n).length+'/5').join('　')}</p>${select('trend','次数更多时，通常怎样',m.trend,[['usually','比例通常更集中，仍有波动'],['exact','每轮都恰好是 1/6'],['same','出现六的次数不变']])}${select('guarantee','能保证更多次每轮都更接近吗',m.guarantee,[['no','不能保证；上面的可能例子就是反例'],['yes','一定能']])}${input('why','这次图上你看到了什么（可选）',m.why)}`;
default:return'';}}
export const render=(t,m)=>`<div id="extra-visual">${visual(t,m)}</div><div id="extra-controls">${controls(t,m)}</div>`;
